    content: dict[str, Any]
    source_ids: list[str]
    created_by: str
    method: Optional[str] = None
    rationale: Optional[str] = None


class WebSearchRequest(BaseModel):
    content: dict[str, Any]
    inputs: list[str]
    created_by: str
    method: Optional[str] = None
    rationale: Optional[str] = None


class AddClaimRequest(BaseModel):
    content: dict[str, Any]
    evidence_ids: list[str]
    created_by: str
