class ProposeRequirementRequest(BaseModel):
    content: dict[str, Any]
    claim_ids: list[str]
    created_by: str
    method: Optional[str] = None
    rationale: Optional[str] = None


class ScoreRequest(BaseModel):
    content: dict[str, Any]
    target_id: str
    formula: str
    created_by: str
